import React from 'react';
import ParticleBackground from './ParticleBackground.jsx';

/**
 * Full-screen mood visuals behind the workspace: particles + dual auroras + edge glow.
 * Keeps App.jsx thinner and isolates animation-layer markup.
 */
const MoodBackdrop = React.memo(function MoodBackdrop({
    moodColors,
    isThinking,
    isTyping,
    particlesEnabled,
}) {
    return (
        <>
            <ParticleBackground
                moodColors={moodColors}
                isThinking={isThinking}
                isTyping={isTyping}
                enabled={particlesEnabled}
            />
            <div
                className="absolute top-0 left-1/2 -translate-x-1/2 w-[800px] h-[340px] pointer-events-none animate-mood-aurora"
                style={{
                    background: `radial-gradient(ellipse 100% 100% at 50% 0%, ${moodColors.dot}26 0%, ${moodColors.dot}0a 50%, transparent 78%)`,
                    filter: 'blur(48px)',
                    transition: 'background 1.8s cubic-bezier(0.4,0,0.2,1)',
                }}
            />
            <div
                className="absolute top-0 left-1/2 -translate-x-1/2 w-[440px] h-[200px] pointer-events-none animate-mood-aurora-2"
                style={{
                    background: `radial-gradient(ellipse 100% 100% at 50% 0%, ${(moodColors.glow || moodColors.dot)}18 0%, transparent 70%)`,
                    filter: 'blur(32px)',
                    transition: 'background 2.2s cubic-bezier(0.4,0,0.2,1)',
                }}
            />
            <div
                className="absolute inset-0 pointer-events-none animate-mood-edge rounded-none z-[1]"
                style={{
                    boxShadow: `inset 0 0 0 1px ${moodColors.dot}1a, inset 0 0 80px ${moodColors.dot}07`,
                    transition: 'box-shadow 1.8s cubic-bezier(0.4,0,0.2,1)',
                }}
            />
        </>
    );
});

export default MoodBackdrop;

import React from 'react';

const SessionLockBanner = React.memo(function SessionLockBanner({
    open,
    sessionError,
    workflowId,
    onUnlock,
}) {
    if (!open) return null;
    return (
        <div
            data-testid="session-lock-banner"
            className="px-5 py-2 border-b border-amber-400/20 bg-amber-400/10 text-[11px] font-mono text-amber-100 flex items-center justify-between gap-3"
        >
            <span>{sessionError || `Session "${workflowId}" is locked.`}</span>
            <button
                type="button"
                data-testid="session-lock-unlock-btn"
                onClick={onUnlock}
                className="px-3 py-1 rounded border border-amber-300/40 text-[10px] uppercase tracking-wider font-bold hover:bg-amber-300/20"
            >
                Unlock Session
            </button>
        </div>
    );
});

export default SessionLockBanner;

import React from 'react';

const OnboardingProgressRail = React.lazy(() => import('./OnboardingProgressRail.jsx'));

const PRESETS = ['compact', 'balanced', 'wide'];

const LayoutControlBar = React.memo(function LayoutControlBar({
    activeRailPresetId,
    onApplyRailPreset,
    onResetRailWidths,
    showInlineThreadRail,
    threadRailCollapsed,
    onToggleThreadRailCollapse,
    showInlineWorkbenchRail,
    workbenchRailCollapsed,
    onToggleWorkbenchRailCollapse,
    canOpenThreadRailOverlay,
    leftRailOverlayOpen,
    onToggleLeftRailOverlay,
    canOpenWorkbenchRailOverlay,
    rightRailOverlayOpen,
    onToggleRightRailOverlay,
    firstBootSteps,
    firstBootProgress,
    onReopenFirstBoot,
    onResetFirstBoot,
}) {
    return (
        <div
            data-testid="layout-control-bar"
            className="px-3 py-1 border-b border-white/[0.03] bg-white/[0.01] flex items-center justify-between gap-2 z-10"
        >
            <div className="flex items-center gap-1.5">
                <div className="inline-flex items-center rounded border border-white/[0.06] overflow-hidden">
                    {PRESETS.map((preset) => (
                        <button
                            key={preset}
                            type="button"
                            data-testid={`layout-preset-${preset}-btn`}
                            onClick={() => onApplyRailPreset(preset)}
                            className={`px-2 py-1 text-[9px] font-mono uppercase tracking-wider transition-colors ${
                                activeRailPresetId === preset
                                    ? 'bg-violet-500/20 text-violet-200'
                                    : 'text-slate-500 hover:bg-white/[0.04] hover:text-slate-300'
                            } ${preset !== 'compact' ? 'border-l border-white/[0.06]' : ''}`}
                        >
                            {preset}
                        </button>
                    ))}
                </div>
                <button
                    type="button"
                    data-testid="layout-reset-panels-btn"
                    onClick={onResetRailWidths}
                    className="text-[9px] font-mono text-slate-600 hover:text-slate-400 px-1.5 py-1 rounded hover:bg-white/[0.04] transition-colors"
                >
                    Reset
                </button>
                <span className="w-px h-3 bg-white/[0.06]" />
                {showInlineThreadRail && (
                    <button
                        type="button"
                        data-testid="layout-toggle-thread-inline-btn"
                        onClick={onToggleThreadRailCollapse}
                        className={`text-[9px] font-mono px-1.5 py-1 rounded transition-colors ${
                            threadRailCollapsed
                                ? 'text-cyan-400/70 hover:text-cyan-300'
                                : 'text-slate-500 hover:text-slate-300 hover:bg-white/[0.04]'
                        }`}
                    >
                        {threadRailCollapsed ? 'Flows' : 'Flows'}
                    </button>
                )}
                {showInlineWorkbenchRail && (
                    <button
                        type="button"
                        data-testid="layout-toggle-workbench-inline-btn"
                        onClick={onToggleWorkbenchRailCollapse}
                        className={`text-[9px] font-mono px-1.5 py-1 rounded transition-colors ${
                            workbenchRailCollapsed
                                ? 'text-cyan-400/70 hover:text-cyan-300'
                                : 'text-slate-500 hover:text-slate-300 hover:bg-white/[0.04]'
                        }`}
                    >
                        {workbenchRailCollapsed ? 'Bench' : 'Bench'}
                    </button>
                )}
                {canOpenThreadRailOverlay && (
                    <button
                        type="button"
                        data-testid="layout-toggle-workflows-btn"
                        onClick={onToggleLeftRailOverlay}
                        className={`text-[9px] font-mono px-1.5 py-1 rounded transition-colors ${
                            leftRailOverlayOpen
                                ? 'text-cyan-300 bg-cyan-500/10'
                                : 'text-slate-500 hover:text-slate-300 hover:bg-white/[0.04]'
                        }`}
                    >
                        Flows
                    </button>
                )}
                {canOpenWorkbenchRailOverlay && (
                    <button
                        type="button"
                        data-testid="layout-toggle-workbench-btn"
                        onClick={onToggleRightRailOverlay}
                        className={`text-[9px] font-mono px-1.5 py-1 rounded transition-colors ${
                            rightRailOverlayOpen
                                ? 'text-cyan-300 bg-cyan-500/10'
                                : 'text-slate-500 hover:text-slate-300 hover:bg-white/[0.04]'
                        }`}
                    >
                        Bench
                    </button>
                )}
            </div>
            <React.Suspense fallback={null}>
                <OnboardingProgressRail
                    steps={firstBootSteps}
                    progress={firstBootProgress}
                    onReopen={onReopenFirstBoot}
                    onReset={onResetFirstBoot}
                />
            </React.Suspense>
        </div>
    );
});

export default LayoutControlBar;

