import React from 'react';
import ThreadRail from './ThreadRail.jsx';
import WorkbenchRail from './WorkbenchRail.jsx';

/**
 * Full-screen dimmed overlays for Flows (ThreadRail) and Bench (WorkbenchRail) when opened as floating rails.
 */
const RailOverlays = React.memo(function RailOverlays({
    leftOpen,
    onLeftBackdropClick,
    rightOpen,
    onRightBackdropClick,
    overlayThreadRailWidth,
    onBeginOverlayThreadRailResize,
    onResetThreadRailWidth,
    overlayWorkbenchRailWidth,
    onBeginOverlayWorkbenchRailResize,
    onResetWorkbenchRailWidth,
    sessions,
    workflowId,
    onSelectSession,
    onCreateSession,
    onSaveSession,
    onRetrySave,
    onLockSession,
    saveStatus,
    isSessionUnlocked,
    sessionHydrationStatus,
    autoLockOnBlur,
    onToggleAutoLock,
    auditOnly,
    onUpgradeToPro,
    chatLog,
    stats,
    onExecute,
    onInsertPrompt,
}) {
    return (
        <>
            {leftOpen && (
                <>
                    <div
                        className="fixed inset-0 z-[72] bg-black/55"
                        onClick={onLeftBackdropClick}
                        onKeyDown={(e) => {
                            if (e.key === 'Escape') onLeftBackdropClick();
                        }}
                        role="presentation"
                    />
                    <div className="fixed left-0 top-14 bottom-0 z-[73] flex items-stretch">
                        <ThreadRail
                            sessions={sessions}
                            workflowId={workflowId}
                            onSelectSession={onSelectSession}
                            onCreateSession={onCreateSession}
                            onSaveSession={onSaveSession}
                            onRetrySave={onRetrySave}
                            onLockSession={onLockSession}
                            saveStatus={saveStatus}
                            isSessionUnlocked={isSessionUnlocked}
                            sessionHydrationStatus={sessionHydrationStatus}
                            autoLockOnBlur={autoLockOnBlur}
                            onToggleAutoLock={onToggleAutoLock}
                            auditOnly={auditOnly}
                            onUpgradeToPro={onUpgradeToPro}
                            chatLog={chatLog}
                            widthPx={overlayThreadRailWidth}
                        />
                        <button
                            type="button"
                            role="separator"
                            aria-label="Resize overlay workflow rail"
                            aria-orientation="vertical"
                            data-testid="thread-rail-overlay-resize-handle"
                            onPointerDown={onBeginOverlayThreadRailResize}
                            onDoubleClick={onResetThreadRailWidth}
                            title="Drag to resize overlay. Double-click to reset."
                            className="group z-20 w-2 -mx-1 cursor-col-resize touch-none select-none flex items-stretch"
                        >
                            <span className="mx-auto my-2 w-px bg-white/30 transition-colors group-hover:bg-cyan-300/90" />
                        </button>
                    </div>
                </>
            )}

            {rightOpen && (
                <>
                    <div
                        className="fixed inset-0 z-[72] bg-black/55"
                        onClick={onRightBackdropClick}
                        onKeyDown={(e) => {
                            if (e.key === 'Escape') onRightBackdropClick();
                        }}
                        role="presentation"
                    />
                    <div className="fixed right-0 top-14 bottom-0 z-[73] flex items-stretch">
                        <button
                            type="button"
                            role="separator"
                            aria-label="Resize overlay workbench rail"
                            aria-orientation="vertical"
                            data-testid="workbench-rail-overlay-resize-handle"
                            onPointerDown={onBeginOverlayWorkbenchRailResize}
                            onDoubleClick={onResetWorkbenchRailWidth}
                            title="Drag to resize overlay. Double-click to reset."
                            className="group z-20 w-2 -mx-1 cursor-col-resize touch-none select-none flex items-stretch"
                        >
                            <span className="mx-auto my-2 w-px bg-white/30 transition-colors group-hover:bg-cyan-300/90" />
                        </button>
                        <WorkbenchRail
                            stats={stats}
                            workflowId={workflowId}
                            onExecute={onExecute}
                            onInsertPrompt={onInsertPrompt}
                            auditOnly={auditOnly}
                            widthPx={overlayWorkbenchRailWidth}
                        />
                    </div>
                </>
            )}
        </>
    );
});

export default RailOverlays;

