import React from 'react';

const CommandPalette = React.lazy(() => import('./CommandPalette'));
const SettingsDrawer = React.lazy(() => import('./SettingsDrawer'));

/**
 * Command palette and settings drawer — always mounted conditionally with Suspense
 * so lazy chunks resolve cleanly.
 */
const PaletteAndSettingsLayer = React.memo(function PaletteAndSettingsLayer({
    showPalette,
    onClosePalette,
    showSettings,
}) {
    return (
        <>
            {showPalette && (
                <React.Suspense fallback={null}>
                    <CommandPalette onClose={onClosePalette} />
                </React.Suspense>
            )}
            {showSettings && (
                <React.Suspense fallback={null}>
                    <SettingsDrawer />
                </React.Suspense>
            )}
        </>
    );
});

export default PaletteAndSettingsLayer;

