+const VALID_FACES = new Set(['chrono', 'orbital', 'neongrid', 'minimal', 'tactical']);
+const VALID_ACCENTS = new Set(['violet', 'fuchsia', 'sky', 'emerald', 'amber', 'rose', 'teal']);
+
+function normalizeFace(face) {
+    const safe = String(face || '').trim().toLowerCase();
+    return VALID_FACES.has(safe) ? safe : 'chrono';
+}
+
+function normalizeAccent(accent) {
+    const safe = String(accent || '').trim().toLowerCase();
+    return VALID_ACCENTS.has(safe) ? safe : 'sky';
+}
+
+function normalizeNumber(value, fallback, min, max) {
+    const safe = Number.isFinite(Number(value)) ? Number(value) : fallback;
+    return Math.max(min, Math.min(max, Math.round(safe)));
+}
+
+export function validateClockFacePack(rawPack) {
+    if (!rawPack || typeof rawPack !== 'object') {
+        return { valid: false, reason: 'Invalid pack payload.' };
+    }
+    const version = Number(rawPack.version || 0);
+    if (!Number.isFinite(version) || version < 1) {
+        return { valid: false, reason: 'Unsupported pack version.' };
+    }
+    const face = normalizeFace(rawPack.dashboardClockFace);
+    const accent = normalizeAccent(rawPack.dashboardFaceAccent);
+    return {
+        valid: true,
+        normalized: {
+            version,
+            dashboardClockFace: face,
+            dashboardFaceAccent: accent,
+            dashboardFaceGlowIntensity: normalizeNumber(rawPack.dashboardFaceGlowIntensity, 65, 0, 100),
+            dashboardFaceScale: normalizeNumber(rawPack.dashboardFaceScale, 100, 80, 130),
+            exportedAt: rawPack.exportedAt || new Date().toISOString(),
+            author: String(rawPack.author || 'local'),
+        },
+    };
+}
