+const fs = require('fs');
+const path = require('path');
+const assert = require('assert');
+
+function run() {
+  const target = path.resolve(__dirname, '..', 'src', 'renderer', 'src', 'components', 'TopStatusBar.jsx');
+  const src = fs.readFileSync(target, 'utf8');
+  const regex = /<button[\s\S]*?data-testid="([^"]*-btn)"[\s\S]*?>/g;
+  const failures = [];
+  let match;
+  while ((match = regex.exec(src)) !== null) {
+    const block = match[0];
+    const testId = match[1];
+    if (!/onClick=/.test(block) && !/type="submit"/.test(block)) {
+      failures.push(testId);
+    }
+  }
+  assert.strictEqual(failures.length, 0, `Buttons missing onClick wiring: ${failures.join(', ')}`);
+  console.log('[ui-wiring-health] OK');
+}
+
+run();
